"""Deterministic synthetic performance model for non-GPU validation."""

from __future__ import annotations

import hashlib
import random
from datetime import UTC, datetime, timedelta

from inferbench.models import MatrixPoint, RequestMetric, TrialMetric
from inferbench.statistics import percentile

SIMULATION_NOTICE = (
    "SYNTHETIC DATA — generated by InferBench simulation; no GPU, TensorRT-LLM, "
    "or Nsight Systems execution occurred. Do not represent as hardware measurements."
)


def _rng(seed: int, point: MatrixPoint, trial: int) -> random.Random:
    paired_id = f"c{point.concurrency}-tp{point.tensor_parallel}-{point.precision}-r{point.repetition}"
    material = f"inferbench-sim-v2|{seed}|{paired_id}|{trial}".encode()
    return random.Random(int.from_bytes(hashlib.sha256(material).digest()[:8], "big"))


def simulate_trial(
    point: MatrixPoint,
    trial: int,
    seed: int,
    output_tokens: int,
    request_count: int,
) -> TrialMetric:
    rng = _rng(seed, point, trial)
    precision_factor = 0.72 if point.precision == "fp8" else 1.0
    tp_factor = 1.0 / (1.0 + 0.72 * (point.tensor_parallel - 1))
    concurrency_efficiency = 1.0 / (1.0 + 0.13 * (point.concurrency - 1))
    base_ttft = 38.0 * precision_factor * tp_factor
    base_latency = 245.0 * precision_factor * tp_factor / concurrency_efficiency
    jitter_scale = 0.60 if point.affinity == "pinned" else 1.0
    metrics: list[RequestMetric] = []
    waits: list[float] = []
    synthetic_epoch = datetime(2000, 1, 1, tzinfo=UTC)
    for sequence in range(1, request_count + 1):
        ordinary = rng.gauss(0, 5.5) * jitter_scale
        wait_ms = rng.uniform(35, 90) * jitter_scale if rng.random() < 0.10 else 0.0
        waits.append(wait_ms)
        ttft = max(2.0, base_ttft + ordinary + wait_ms * 0.8)
        latency = max(ttft, base_latency + ordinary * 2.4 + wait_ms)
        started = synthetic_epoch + timedelta(seconds=sequence)
        metrics.append(
            RequestMetric(
                request_id=f"synthetic-{point.point_id}-t{trial}-q{sequence}",
                sequence=sequence,
                success=True,
                started_at=started.isoformat(),
                finished_at=(started + timedelta(milliseconds=latency)).isoformat(),
                ttft_ms=round(ttft, 3),
                latency_ms=round(latency, 3),
                completion_tokens=output_tokens,
                total_tokens=output_tokens,
                finish_reason="length",
                http_status=200,
                events=2,
            )
        )
    wall_seconds = sum(
        max(metric.latency_ms for metric in metrics[index:index + point.concurrency])
        for index in range(0, request_count, point.concurrency)
    ) / 1000.0
    ttft_values = [float(metric.ttft_ms) for metric in metrics if metric.ttft_ms is not None]
    latency_values = [metric.latency_ms for metric in metrics]
    return TrialMetric(
        trial=trial,
        repetition=point.repetition,
        status="completed",
        concurrency=point.concurrency,
        request_count=request_count,
        successful_requests=request_count,
        failed_requests=0,
        wall_time_s=round(wall_seconds, 6),
        throughput_tokens_s=round(request_count * output_tokens / wall_seconds, 3),
        ttft_p50_ms=round(percentile(ttft_values, 0.50), 3),
        ttft_p99_ms=round(percentile(ttft_values, 0.99), 3),
        latency_p50_ms=round(percentile(latency_values, 0.50), 3),
        latency_p99_ms=round(percentile(latency_values, 0.99), 3),
        selected_os_runtime_wait_ms=round(max(waits), 3),
        requests=metrics,
    )
